function guess(p){const r=floor().rooms.find(r=>!r.localSteps&&!isStair(r)&&!['void','solid'].includes(r.type)&&(window.KERN_SHAPES.contains(p,r)||window.KERN_SHAPES.edges(r).some(e=>window.KERN_SHAPES.project(p,e).distance<=.3)));return r?{kind:'room',floor:floorId,room:r.id}:{kind:'site'};}
function make(a,b,free=false){const snap=free?cleanNumber:window.snap;const start=guess(a),end=guess(b),az=E.value(model,start,floor().z),bz=E.value(model,end,az+.85),r=window.KERN_ROUTE_STAIRS.create([[snap(a.x),snap(a.y)],[snap(b.x),snap(b.y)]],{id:uniqueId('localsteps-'),name:'Local steps',width:window.KERN_AUTHORING_3D?.width()||1.5,startZ:az,endZ:Math.abs(bz-az)<.01?az+.85:bz,start,end:Math.abs(bz-az)<.01?undefined:end,hostRoom:start.room});r.routeStair.nodes.forEach(n=>n.landingDepth=.35);r.cutoutFor=[start.room,end.room].filter(Boolean);changed(()=>{floor().rooms.push(r);setSelection({rooms:[r.id]});tool='select';});}
