function cancel(){const d=drawing;drawing=null;if(d&&$('plan').hasPointerCapture(d.pointerId))$('plan').releasePointerCapture(d.pointerId);draw();}window.addEventListener('blur',()=>{if(drawing)cancel();});$('plan').addEventListener('pointercancel',()=>{if(drawing)cancel();});$('plan').addEventListener('lostpointercapture',()=>{if(drawing)cancel();});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawing){stop(e);cancel();setTool('select');}},true);
function overlay(){if(!drawing)return '';if(drawing.floor!==floorId||drawing.building!==currentBuilding().id||tool!=='local-steps'){drawing=null;return '';}const a=drawing.a,b=drawing.b;return `<rect x="${Math.min(a.x,b.x)}" y="${Math.min(a.y,b.y)}" width="${Math.abs(a.x-b.x)}" height="${Math.abs(a.y-b.y)}" fill="#e7b16b33" stroke="#e7b16b" stroke-width="${screenUnits(2)}" pointer-events="none"/>`;}
const originalValidate=validateImport;validateImport=function(p){originalValidate(p);if(p.siteGroundZ!==undefined&&(!Number.isFinite(p.siteGroundZ)||Math.abs(p.siteGroundZ)>150))throw Error('Invalid outside ground elevation');if(p.splitLevelConnections!==undefined&&(!Array.isArray(p.splitLevelConnections)||p.splitLevelConnections.length>300))throw Error('Invalid local stair collection');for(const c of p.splitLevelConnections||[]){if(!c.localSteps)continue;const f=p.floors[c.floor],r=f?.rooms.find(r=>r.id===c.room);if(c.targetRiser!==undefined&&(!Number.isFinite(c.targetRiser)||c.targetRiser<.1||c.targetRiser>.22))throw Error('Local stair riser target must be 0.10–0.22 m');if(!r||!['x','y'].includes(c.runAxis)||![c.lowerZ,c.upperZ].every(z=>Number.isFinite(z)&&Math.abs(z)<=150))throw Error('Invalid local stair endpoints');for(const ref of [c.start,c.end])if(ref&&(!['site','floor','room'].includes(ref.kind)||ref.offset!==undefined&&(!Number.isFinite(ref.offset)||Math.abs(ref.offset)>150)||ref.kind!=='site'&&typeof ref.floor!=='string'||ref.kind==='room'&&(typeof ref.room!=='string'||ref.room===c.room)))throw Error('Invalid linked stair surface');}return p;};
